341	/// Splits `hits` among `blocks`: a hit goes to every block whose own text on that line matches, except one that holds
342	/// a smaller such block. A class or object therefore keeps only the matches outside its members, and a block with
343	/// none is dropped by the caller. A block can start or end in the middle of a line (`} b() {`, `}, // note`), so only
344	/// the part of the line inside the block counts, which sends the match to the member or holder that actually contains
345	/// the text. Where no block's own text matches (a match across the edge of every block on the line) every block on the
346	/// line keeps the hit, so a match is never lost. Blocks that only share a line are not nested, so each keeps it.
347	/// `hits` must be in line order; each block's hits are too.
348	fn owned_hits<'h>(
349	    blocks: &[CodeBlock],
350	    hits: &'h [LineHit],
351	    line_matches: &dyn Fn(&str) -> bool,
352	) -> Vec<Vec<&'h LineHit>> {
353	    let mut containing: Vec<Vec<usize>> = vec![Vec::new(); hits.len()];
354	    for (index, block) in blocks.iter().enumerate() {
355	        let first = hits.partition_point(|hit| hit.line_number < block.line_start);
356	        let inside = hits[first..].iter().take_while(|hit| hit.line_number <= block.line_end).count();
357	        for slot in &mut containing[first..first + inside] {
358	            slot.push(index);
359	        }
360	    }
361	    let range = |index: usize| (blocks[index].line_start, blocks[index].line_end);
362	    let own_text_matches = |index: usize, line: usize| {
363	        let block = &blocks[index];
364	        block.code.split('\n').nth(line - block.line_start).is_some_and(line_matches)
365	    };
366	    let mut per_block = vec![Vec::new(); blocks.len()];
367	    for (hit, containing_all) in hits.iter().zip(&containing) {
368	        let matching: Vec<usize> =
369	            containing_all.iter().copied().filter(|&index| own_text_matches(index, hit.line_number)).collect();
370	        let candidates = if matching.is_empty() { containing_all } else { &matching };
371	        for &outer in candidates {
372	            let (start, end) = range(outer);
373	            let holds_a_smaller_block = candidates.iter().any(|&inner| {
374	                let (inner_start, inner_end) = range(inner);
375	                inner_start >= start && inner_end <= end && (inner_start, inner_end) != (start, end)
376	            });
377	            if !holds_a_smaller_block {
378	                per_block[outer].push(hit);
379	            }
380	        }
381	    }
382	    per_block
383	}
