389	    }
390	    // `regex::escape` only ever puts a backslash before the character it escapes.
391	    let mut text = String::with_capacity(term.pattern.len());
392	    let mut chars = term.pattern.chars();
393	    while let Some(ch) = chars.next() {
394	        if ch == '\\' {
395	            text.extend(chars.next());
396	        } else {
397	            text.push(ch);
398	        }
399	    }
400	    text
